def dedupe(items):
    """保留每个值第一次出现的位置，后面再出现的全部去掉，保持原有顺序。"""
    out = []
    seen = set()
    for x in items:
        try:
            if x in seen:
                continue
            seen.add(x)
        except TypeError:
            # 不可哈希的元素退化为线性查找
            if x in out:
                continue
        out.append(x)
    return out
